<span class="line"><span style="--shiki-light:#E06C75;--shiki-dark:#89DDFF;">  &quot;</span><span style="--shiki-light:#E06C75;--shiki-dark:#C792EA;">description</span><span style="--shiki-light:#E06C75;--shiki-dark:#89DDFF;">&quot;</span><span style="--shiki-light:#ABB2BF;--shiki-dark:#89DDFF;">:</span><span style="--shiki-light:#98C379;--shiki-dark:#89DDFF;"> &quot;&quot;</span><span style="--shiki-light:#ABB2BF;--shiki-dark:#89DDFF;">,</span></span>
